// SPDX-License-Identifier: MIT
//! Differential anchor against bnb-chain/tss-lib v3.0.0 (MIT), through key
//! material — the one thing two GG18/GG20 implementations with different
//! Fiat-Shamir transcripts can exchange. `tsslib_vectors.zig` is generated by
//! `tools/tsslib` (see its README):
//!
//! - `tsslib_keygen` — tss-lib's own DEALER-FREE keygen, 2-of-3, with the
//!   three signatures tss-lib made with it. This module must sign with that
//!   material (Shamir indices, Lagrange weights, Paillier keys, ring-Pedersen
//!   tuples all read the way tss-lib means them), and tss-lib's tuples must
//!   pass this module's Πprm/Πmod proofs of correct generation.
//! - `zig_keys_tsslib_signed` — material from this module's trusted-dealer
//!   keygen and safe-prime generator, with the three signatures tss-lib made
//!   after importing it (`go run . sign` exits non-zero unless each verifies).

const std = @import("std");
const builtin = @import("builtin");
const paillier = @import("paillier");
const root = @import("root.zig");
const signing = @import("signing.zig");
const aux_proofs = @import("aux_proofs.zig");
const vectors = @import("tsslib_vectors.zig");

const testing = std.testing;

fn unhex(allocator: std.mem.Allocator, hex: []const u8) ![]u8 {
    const out = try allocator.alloc(u8, (hex.len + 1) / 2);
    errdefer allocator.free(out);
    if (hex.len % 2 == 1) {
        // Leading nibble of an odd-length (minimal) big-endian hex string.
        out[0] = try std.fmt.parseInt(u8, hex[0..1], 16);
        _ = try std.fmt.hexToBytes(out[1..], hex[1..]);
    } else {
        _ = try std.fmt.hexToBytes(out, hex);
    }
    return out;
}

fn fixed(comptime n: usize, hex: []const u8) ![n]u8 {
    var out: [n]u8 = undefined;
    if (hex.len != 2 * n) return error.BadVector;
    _ = try std.fmt.hexToBytes(&out, hex);
    return out;
}

fn auxFe(allocator: std.mem.Allocator, nt: root.AuxModulus, hex: []const u8) !root.AuxFe {
    const b = try unhex(allocator, hex);
    defer allocator.free(b);
    return root.AuxFe.fromBytes(nt, b, .big);
}

const Loaded = struct {
    shares: []root.KeyShare,
    entries: []root.PartyPublicKeys,
    trapdoors: []root.AuxTrapdoor,
    public_key: root.Element,

    fn deinit(self: Loaded, allocator: std.mem.Allocator) void {
        for (self.trapdoors) |t| t.deinit(allocator);
        allocator.free(self.trapdoors);
        allocator.free(self.entries);
        allocator.free(self.shares);
    }
};

/// Builds this module's `KeyShare`s from an interchange key set, checking
/// on the way that each `big_x` is `x·G`.
fn load(allocator: std.mem.Allocator, set: vectors.KeySet) !Loaded {
    const n = set.parties.len;
    const shares = try allocator.alloc(root.KeyShare, n);
    errdefer allocator.free(shares);
    const entries = try allocator.alloc(root.PartyPublicKeys, n);
    errdefer allocator.free(entries);
    const trapdoors = try allocator.alloc(root.AuxTrapdoor, n);
    var made: usize = 0;
    errdefer {
        for (trapdoors[0..made]) |t| t.deinit(allocator);
        allocator.free(trapdoors);
    }
    const public_key = try root.Element.fromBytes(try fixed(33, set.public_key));
    for (set.parties, 0..) |p, i| {
        const pp = try unhex(allocator, p.paillier_p);
        defer allocator.free(pp);
        const pq = try unhex(allocator, p.paillier_q);
        defer allocator.free(pq);
        const kp = try paillier.fromPrimes(pp, pq);
        const nt_bytes = try unhex(allocator, p.n_tilde);
        defer allocator.free(nt_bytes);
        const nt = try root.AuxModulus.fromBytes(nt_bytes, .big);
        const x = try root.Scalar.fromBytes(try fixed(32, p.x), .big);
        const big_x = try root.Element.fromBytes(try fixed(33, p.big_x));
        const x_g = try root.Secp256k1.basePoint.mul(x.toBytes(.big), .big);
        try testing.expect(x_g.equivalent(try big_x.point()));

        entries[i] = .{
            .index = p.index,
            .paillier_pk = kp.public,
            .aux = .{ .n_tilde = nt, .h1 = try auxFe(allocator, nt, p.h1), .h2 = try auxFe(allocator, nt, p.h2) },
            .verifying_share = big_x,
        };
        const tp = try unhex(allocator, p.aux_p_safe);
        errdefer allocator.free(tp);
        const tq = try unhex(allocator, p.aux_q_safe);
        // `aux_lambda` is tss-lib's Alpha (h2 = h1^Alpha); the trapdoor is its inverse.
        trapdoors[i] = .{ .p = tp, .q = tq, .lambda = try root.auxLogInverse(nt, tp, tq, try auxFe(allocator, nt, p.aux_lambda)) };
        made += 1;
        shares[i] = .{
            .index = p.index,
            .t = set.t,
            .n = set.n,
            .secret_share = x,
            .group_public_key = public_key,
            .verifying_share = big_x,
            .paillier_secret = kp.secret,
            .public_keys = undefined,
        };
    }
    for (shares) |*s| s.public_keys = .{ .entries = entries };
    return .{ .shares = shares, .entries = entries, .trapdoors = trapdoors, .public_key = public_key };
}

fn verifyCommittedSignatures(set: vectors.KeySet, public_key: root.Element) !void {
    const pk = try signing.ecdsa.PublicKey.fromSec1(&public_key.toBytes());
    try testing.expectEqual(@as(usize, 3), set.signatures.len);
    for (set.signatures) |s| {
        const sig: signing.Signature = .{ .r = try fixed(32, s.r), .s = try fixed(32, s.s) };
        try sig.verify(set.message, pk);
    }
}

test "tss-lib keygen output: this module signs with it; tss-lib's ring-Pedersen tuples pass Πprm/Πmod" {
    if (builtin.mode == .Debug) return error.SkipZigTest;
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x7473_736c_6962_41); // "tsslibA"
    const random = prng.random();

    const set = vectors.tsslib_keygen;
    const loaded = try load(allocator, set);
    defer loaded.deinit(allocator);
    try verifyCommittedSignatures(set, loaded.public_key);

    // Every 2-subset: this module's state machines sign, std ECDSA verifies
    // under tss-lib's group key.
    const pk = try signing.ecdsa.PublicKey.fromSec1(&loaded.public_key.toBytes());
    const pairs = [_][2]usize{ .{ 0, 1 }, .{ 0, 2 }, .{ 1, 2 } };
    for (pairs) |pair| {
        const subset = [_]root.KeyShare{ loaded.shares[pair[0]], loaded.shares[pair[1]] };
        const sig = try signing.signWithShares(allocator, &subset, set.message, random);
        try sig.verify(set.message, pk);
    }

    // tss-lib's N-tilde are Blum products with ⟨h1⟩ = ⟨h2⟩: our proofs of
    // correct generation (h1 ∈ ⟨h2⟩), made from tss-lib's trapdoor, verify.
    for (loaded.entries, loaded.trapdoors) |e, td| {
        const proof = try aux_proofs.proveWellFormed(allocator, e.aux, td, random);
        try aux_proofs.verifyWellFormed(e.aux, proof, random);
    }
}

test "this module's key material: tss-lib signed with it (committed signatures verify), and so does this module" {
    if (builtin.mode == .Debug) return error.SkipZigTest;
    const allocator = testing.allocator;
    var prng = std.Random.DefaultPrng.init(0x7473_736c_6962_42); // "tsslibB"
    const random = prng.random();

    const set = vectors.zig_keys_tsslib_signed;
    const loaded = try load(allocator, set);
    defer loaded.deinit(allocator);
    try verifyCommittedSignatures(set, loaded.public_key);

    const pk = try signing.ecdsa.PublicKey.fromSec1(&loaded.public_key.toBytes());
    const sig = try signing.signWithShares(allocator, loaded.shares[1..3], set.message, random);
    try sig.verify(set.message, pk);
}

test "auxParamsWithTrapdoorFromSafePrimes: tss-lib's safe primes give tss-lib's Ñ, and our Πprm/Πmod over it verify" {
    if (builtin.mode == .Debug) return error.SkipZigTest;
    const allocator = testing.allocator;
    const pp = vectors.tsslib_keygen.parties[0];
    var p: [128]u8 = undefined;
    var q: [128]u8 = undefined;
    _ = try std.fmt.hexToBytes(&p, pp.aux_p_safe);
    _ = try std.fmt.hexToBytes(&q, pp.aux_q_safe);
    var prng = std.Random.DefaultPrng.init(0x6175_7867_656e);
    const random = prng.random();
    const gen = try root.auxParamsWithTrapdoorFromSafePrimes(allocator, &p, &q, random);
    defer gen.trapdoor.deinit(allocator);

    var want: [256]u8 = undefined;
    const want_s = try std.fmt.hexToBytes(&want, pp.n_tilde);
    var got: [root.aux_modulus_bytes]u8 = undefined;
    try gen.params.n_tilde.toBytes(&got, .big);
    try testing.expectEqualSlices(u8, want_s, got[got.len - want_s.len ..]);

    const proof = try aux_proofs.proveWellFormedBound(allocator, gen.params, gen.trapdoor, "auxgen", random);
    try aux_proofs.verifyWellFormedBound(gen.params, "auxgen", proof, random);
}
